public class Main {
    interface BeanNameAware { void setBeanName(String n); }
    interface BeanFactoryAware { void setBeanFactory(Object bf); }

    static class MyBean implements BeanNameAware, BeanFactoryAware {
        String name;
        Object factory;
        public void setBeanName(String n) { this.name = n; }
        public void setBeanFactory(Object bf) { this.factory = bf; }
        String desc() { return "name=" + name + ", hasFactory=" + (factory != null); }
    }

    public static void main(String[] args) {
        MyBean b = new MyBean();
        ((BeanNameAware) b).setBeanName("myBean");
        ((BeanFactoryAware) b).setBeanFactory("BeanFactory@mini");
        System.out.println(b.desc());
    }
}
